package co.edu.umb.boleteria.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.sql.*;import java.util.*;
@Service public class ClusterService {
 @Value("${POSTGRES_DB}") String db;@Value("${POSTGRES_USER}") String user;@Value("${POSTGRES_PASSWORD}") String pass;
 private Map<String,Object> node(String host){Map<String,Object> m=new LinkedHashMap<>();m.put("nodo",host);try(Connection c=DriverManager.getConnection("jdbc:postgresql://"+host+":5432/"+db+"?connectTimeout=2&socketTimeout=3",user,pass);Statement s=c.createStatement()){s.setQueryTimeout(3);try(ResultSet r=s.executeQuery("select pg_is_in_recovery(),current_setting('cluster_name')")){r.next();m.put("alcanzable",true);m.put("enRecuperacion",r.getBoolean(1));m.put("clusterName",r.getString(2));}}catch(Exception e){m.put("alcanzable",false);m.put("error","NO_DISPONIBLE");}return m;}
 public Map<String,Object> estado(){var p=node("nodo_centos_primary");var r=node("nodo_centos_secondary");List<Map<String,Object>> replicas=new ArrayList<>();if(Boolean.TRUE.equals(p.get("alcanzable")))try(Connection c=DriverManager.getConnection("jdbc:postgresql://nodo_centos_primary:5432/"+db+"?connectTimeout=2",user,pass);Statement s=c.createStatement();ResultSet rs=s.executeQuery("select state,sync_state,extract(epoch from replay_lag)*1000 replay_lag_ms from pg_stat_replication")){while(rs.next())replicas.add(Map.of("state",rs.getString(1),"syncState",rs.getString(2),"replayLagMs",rs.getObject(3)==null?"":rs.getObject(3)));}catch(Exception ignored){}return Map.of("nodos",List.of(p,r),"replicacion",replicas);}
}
